"""Original treatment illustrations (SVG) in the South Cairns Dental palette.
These are illustrations, not photographs. Run: python3 _build/make_illustrations.py"""
from pathlib import Path
OUT = Path(__file__).resolve().parent.parent / "assets/images/illustrations"
C = dict(canopy="#12302A", forest="#1E4A3F", fern="#2E6B5A", lime="#AEC953", wash="#EEF4D6",
         mist="#EEF3EC", mint="#DCE9E2", white="#FFFFFF", gum="#C98E86", alert="#A3302A")
MOLAR = "M-40,-60 C-40,-82 -14,-86 0,-72 C14,-86 40,-82 40,-60 C42,-30 32,-15 28,10 C24,40 18,62 10,62 C2,62 4,26 0,26 C-4,26 -2,62 -10,62 C-18,62 -24,40 -28,10 C-32,-15 -42,-30 -40,-60 Z"
CROWN_TOP = "M-40,-60 C-40,-82 -14,-86 0,-72 C14,-86 40,-82 40,-60 C41,-42 37,-30 33,-18 L-33,-18 C-37,-30 -41,-42 -40,-60 Z"
def tooth(x, y, s=1.0, fill=C["white"], stroke=C["forest"], extra=""):
    return f'<g transform="translate({x} {y}) scale({s})"><path d="{MOLAR}" fill="{fill}" stroke="{stroke}" stroke-width="{4/s:.2f}" stroke-linejoin="round"/>{extra}</g>'
def frame(bg, body, accent=C["lime"], cx=300, cy=70, r=46):
    return f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 300" preserveAspectRatio="xMidYMid slice" role="img">
<rect width="400" height="300" fill="{bg}"/>
<circle cx="{cx}" cy="{cy}" r="{r}" fill="{accent}" opacity=".55"/>
<path d="M0,240 C80,215 150,250 230,232 C300,216 350,236 400,226 L400,300 L0,300 Z" fill="{C['white']}" opacity=".45"/>
{body}</svg>'''
spark = lambda x, y, s=1, col=C["lime"]: f'<path transform="translate({x} {y}) scale({s})" d="M0,-12 L3,-3 L12,0 L3,3 L0,12 L-3,3 L-12,0 L-3,-3 Z" fill="{col}"/>'
gum = lambda y=205, col=C["fern"]: f'<path d="M90,{y} C140,{y-16} 260,{y-16} 310,{y} L310,{y+60} L90,{y+60} Z" fill="{col}"/>'
art = {}
art["check-ups"] = frame(C["mint"], tooth(200, 150, 1.25) + f'<g transform="translate(272 168) rotate(-35)"><rect x="-4" y="0" width="8" height="90" rx="4" fill="{C["forest"]}"/><circle cx="0" cy="-14" r="18" fill="{C["white"]}" stroke="{C["forest"]}" stroke-width="5"/></g>' + spark(130, 90) + spark(150, 62, .6))
art["childrens"] = frame(C["wash"], tooth(200, 150, 1.2, extra=f'<circle cx="-14" cy="-40" r="5" fill="{C["forest"]}"/><circle cx="14" cy="-40" r="5" fill="{C["forest"]}"/><path d="M-16,-22 C-8,-12 8,-12 16,-22" fill="none" stroke="{C["forest"]}" stroke-width="4" stroke-linecap="round"/>') + spark(110, 80, 1.2) + spark(292, 150, .9, C["fern"]) + spark(270, 210, .6))
art["veneers"] = frame(C["mist"], tooth(185, 150, 1.25) + f'<g transform="translate(232 150) scale(1.25)"><path d="M-2,-74 C14,-84 38,-80 40,-60 C42,-36 34,-20 30,0" fill="none" stroke="{C["lime"]}" stroke-width="7" stroke-linecap="round"/></g>' + spark(300, 190, .8))
art["crowns"] = frame(C["mint"], f'<g transform="translate(200 175) scale(1.2)"><path d="M-30,-18 L30,-18 C26,10 20,40 10,40 C4,40 4,14 0,14 C-4,14 -4,40 -10,40 C-20,40 -26,10 -30,-18 Z" fill="{C["white"]}" stroke="{C["forest"]}" stroke-width="3.4"/></g><g transform="translate(200 120) scale(1.2)"><path d="{CROWN_TOP}" fill="{C["lime"]}" stroke="{C["forest"]}" stroke-width="3.4"/></g>' + f'<path d="M200,40 L200,58 M192,50 L200,58 L208,50" fill="none" stroke="{C["forest"]}" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/>')
art["implants"] = frame(C["mist"], gum(200) + f'<g transform="translate(200 104) scale(1.05)"><path d="{CROWN_TOP}" fill="{C["white"]}" stroke="{C["forest"]}" stroke-width="3.8"/></g><rect x="186" y="86" width="28" height="22" rx="4" fill="{C["lime"]}" stroke="{C["forest"]}" stroke-width="3.5"/>' + "".join(f'<rect x="{188+i*0.6:.1f}" y="{112+i*16}" width="{24-i*1.2:.1f}" height="10" rx="3" fill="{C["white"]}" stroke="{C["forest"]}" stroke-width="3"/>' for i in range(6)), cx=100, cy=80)
art["dentures"] = frame(C["wash"], f'<path d="M80,190 C80,100 320,100 320,190 L292,190 C292,130 108,130 108,190 Z" fill="{C["fern"]}"/>' + "".join(tooth(200 + 100*__import__("math").cos(a), 182 - 72*__import__("math").sin(a), .36) for a in [0.25, 0.65, 1.05, 1.45, 1.85, 2.25, 2.65, 2.95]), cx=320, cy=60, r=36)
art["emergency"] = frame(C["mist"], tooth(195, 150, 1.25, extra=f'<path d="M6,-74 L-6,-48 L8,-30 L-4,-6" fill="none" stroke="{C["alert"]}" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/>') + f'<circle cx="290" cy="110" r="20" fill="{C["alert"]}"/><rect x="287" y="98" width="6" height="15" rx="3" fill="#fff"/><circle cx="290" cy="120" r="3.2" fill="#fff"/>', accent=C["mint"])
art["extractions"] = frame(C["mint"], gum(214) + f'<path d="M168,214 C178,240 222,240 232,214" fill="{C["canopy"]}" opacity=".35"/>' + tooth(200, 126, 1.05) + f'<path d="M150,206 L150,188 M250,206 L250,188" stroke="{C["forest"]}" stroke-width="4" stroke-linecap="round" opacity=".5"/>')
art["fillings"] = frame(C["wash"], tooth(200, 150, 1.25, extra=f'<path d="M-18,-64 C-10,-56 12,-58 18,-66 C22,-48 8,-38 -4,-40 C-14,-42 -20,-52 -18,-64 Z" fill="{C["lime"]}" stroke="{C["forest"]}" stroke-width="2.4"/>') + spark(285, 120, .9, C["fern"]))
art["invisalign"] = frame(C["mist"], "".join(tooth(110 + i*60, 160, .62) for i in range(4)) + f'<path d="M72,108 C80,92 320,92 328,108 L330,170 C320,196 80,196 70,170 Z" fill="{C["white"]}" fill-opacity=".35" stroke="{C["fern"]}" stroke-width="4" stroke-dasharray="2 0"/>', cx=320, cy=56, r=34)
art["mouthguards"] = frame(C["mint"], f'<path d="M90,110 C90,250 310,250 310,110 L268,110 C268,200 132,200 132,110 Z" fill="{C["lime"]}" stroke="{C["forest"]}" stroke-width="5" stroke-linejoin="round"/><path d="M110,118 C112,214 288,214 290,118" fill="none" stroke="{C["forest"]}" stroke-width="3" stroke-dasharray="8 8" opacity=".6"/>', cx=320, cy=60, r=34)
art["root-canal"] = frame(C["wash"], tooth(200, 150, 1.3, extra=f'<path d="M-22,-50 C-22,-62 22,-62 22,-50 C22,-30 12,-20 8,0 C6,20 6,40 8,52 M-8,52 C-6,40 -6,20 -8,0 C-12,-20 -22,-30 -22,-50" fill="{C["alert"]}" fill-opacity=".18" stroke="{C["alert"]}" stroke-width="3" stroke-linecap="round"/>'), accent=C["mint"])
art["whitening"] = frame(C["mint"], tooth(200, 152, 1.2) + "".join(f'<path d="M{200+90*__import__("math").cos(a):.0f},{140-90*__import__("math").sin(a):.0f} L{200+118*__import__("math").cos(a):.0f},{140-118*__import__("math").sin(a):.0f}" stroke="{C["lime"]}" stroke-width="8" stroke-linecap="round"/>' for a in [0.35, 0.9, 1.57, 2.24, 2.79]), accent=C["white"])
art["wisdom"] = frame(C["mist"], gum(208) + tooth(140, 170, .7) + tooth(205, 170, .7) + f'<g transform="translate(272 196) rotate(-28) scale(.7)"><path d="{MOLAR}" fill="{C["lime"]}" stroke="{C["forest"]}" stroke-width="5.7"/></g>', cx=90, cy=70, r=38)
# Scenes for homepage/About
art["scene-comfort"] = frame(C["wash"], f'<path d="M140,150 a60,60 0 0 1 120,0" fill="none" stroke="{C["forest"]}" stroke-width="12" stroke-linecap="round"/><rect x="122" y="140" width="34" height="56" rx="14" fill="{C["lime"]}" stroke="{C["forest"]}" stroke-width="5"/><rect x="244" y="140" width="34" height="56" rx="14" fill="{C["lime"]}" stroke="{C["forest"]}" stroke-width="5"/><path d="M300,96 l0,-40 l26,-6 l0,40" fill="none" stroke="{C["fern"]}" stroke-width="5"/><circle cx="294" cy="98" r="9" fill="{C["fern"]}"/><circle cx="320" cy="92" r="9" fill="{C["fern"]}"/>', accent=C["mint"], cx=90, cy=70, r=40)
art["scene-family"] = frame(C["mint"], tooth(150, 160, 1.0) + tooth(255, 182, .62, extra=f'<circle cx="-14" cy="-40" r="6" fill="{C["forest"]}"/><circle cx="14" cy="-40" r="6" fill="{C["forest"]}"/><path d="M-16,-22 C-8,-12 8,-12 16,-22" fill="none" stroke="{C["forest"]}" stroke-width="6" stroke-linecap="round"/>') + spark(300, 100, 1))
art["scene-prevent"] = frame(C["mist"], f'<g transform="translate(150 150) rotate(-30)"><rect x="-8" y="-20" width="16" height="140" rx="8" fill="{C["forest"]}"/><rect x="-14" y="-74" width="28" height="56" rx="8" fill="{C["white"]}" stroke="{C["forest"]}" stroke-width="4"/>' + "".join(f'<line x1="{-8+i*5}" y1="-70" x2="{-8+i*5}" y2="-52" stroke="{C["lime"]}" stroke-width="3"/>' for i in range(4)) + f'</g><rect x="230" y="96" width="70" height="120" rx="14" fill="{C["lime"]}" stroke="{C["forest"]}" stroke-width="5"/><rect x="246" y="80" width="38" height="20" rx="5" fill="{C["forest"]}"/><circle cx="265" cy="156" r="18" fill="{C["white"]}"/>', accent=C["wash"])
for k, v in art.items():
    (OUT / f"{k}.svg").write_text(v.replace('role="img">', f'role="img" aria-hidden="true">'))
print(len(art), "illustrations")
